// The math library of the PTX backend: `libm/libm.ptx`, generated by `libm/gen.sh` from musl and
// our C (`libm/sj/`), split into its functions and tables so that a module includes only what
// its kernel calls.
//
// The entry points are `__sj_<op>` (real: `double f(double[, double])`) and `__sj_cplx_<op>`
// (complex: `cplx f(double re, double im[, double re2, double im2])`, the struct returned in a
// 16-byte `.param`), <op> being symjit's name of the function; the internal functions and tables
// are `__sjm_*` (libm/post.py).

use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

const LIBM: &str = include_str!("libm/libm.ptx");

/// The signature of an entry point.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Signature {
    pub count_params: usize,
    /// returns `struct { double re, im; }`
    pub complex: bool,
}

/// One top-level statement of the library: a function (declaration or definition) or a table.
struct Chunk {
    name: String,
    text: String,
    /// the indices of the chunks it refers to
    deps: Vec<usize>,
}

struct Library {
    chunks: Vec<Chunk>,
    /// the chunks of each name (a function may have a forward declaration and its definition)
    by_name: HashMap<String, Vec<usize>>,
    entries: HashMap<String, Signature>,
}

fn library() -> &'static Library {
    static LIBRARY: OnceLock<Library> = OnceLock::new();
    LIBRARY.get_or_init(|| parse(LIBM))
}

fn is_ident_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '$'
}

/// The identifiers of `text` that start with `__sj`.
fn library_names(text: &str) -> impl Iterator<Item = &str> {
    text.split(|c: char| !is_ident_char(c))
        .filter(|w| w.starts_with("__sj"))
}

/// The name a statement defines or declares: for `.func`, the identifier after the optional
/// return parameter; for `.global`, the one before `[`.
fn chunk_name(head: &str) -> Option<String> {
    let head = head.trim();
    if let Some(pos) = head.find(".func") {
        let mut rest = head[pos + 5..].trim_start();
        if rest.starts_with('(') {
            rest = rest[rest.find(')')? + 1..].trim_start();
        }
        let name: String = rest.chars().take_while(|c| is_ident_char(*c)).collect();
        (!name.is_empty()).then_some(name)
    } else if head.contains(".global") {
        let before = &head[..head.find('[')?];
        before
            .rsplit(|c: char| !is_ident_char(c))
            .next()
            .filter(|n| !n.is_empty())
            .map(String::from)
    } else {
        None
    }
}

fn parse(text: &str) -> Library {
    let mut chunks: Vec<Chunk> = Vec::new();
    let mut lines = text.lines().peekable();

    while let Some(line) = lines.next() {
        let t = line.trim();
        if t.is_empty()
            || t.starts_with("//")
            || t.starts_with(".version")
            || t.starts_with(".target")
            || t.starts_with(".address_size")
        {
            continue;
        }
        let mut stmt = String::from(line);
        stmt.push('\n');
        if !t.ends_with(';') {
            // a function: its parameters, then `;` (a declaration) or a body in braces
            let mut depth = 0i32;
            for line in lines.by_ref() {
                stmt.push_str(line);
                stmt.push('\n');
                let t = line.trim();
                if t == "{" {
                    depth += 1;
                } else if t == "}" {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                } else if t == ";" && depth == 0 {
                    break;
                }
            }
        }
        let name = chunk_name(t).unwrap_or_else(|| panic!("libm.ptx: cannot parse `{}`", t));
        chunks.push(Chunk {
            name,
            text: stmt,
            deps: Vec::new(),
        });
    }

    let mut by_name: HashMap<String, Vec<usize>> = HashMap::new();
    for (i, c) in chunks.iter().enumerate() {
        by_name.entry(c.name.clone()).or_default().push(i);
    }

    for c in chunks.iter_mut() {
        let mut deps: Vec<usize> = Vec::new();
        for w in library_names(&c.text) {
            if w != c.name {
                if let Some(idx) = by_name.get(w) {
                    deps.extend(idx);
                }
            }
        }
        deps.sort_unstable();
        deps.dedup();
        c.deps = deps;
    }

    let mut entries = HashMap::new();
    for c in chunks.iter() {
        if let Some(op) = c.name.strip_prefix("__sj_") {
            let head = &c.text[..c.text.find(')').unwrap_or(0)];
            let complex = head.contains(".b8 func_retval0[16]");
            let count_params = c.text[..c.text.find(['{', ';']).unwrap_or(c.text.len())]
                .matches(".param")
                .count()
                - 1;
            entries.insert(
                op.to_string(),
                Signature {
                    count_params,
                    complex,
                },
            );
        }
    }

    Library {
        chunks,
        by_name,
        entries,
    }
}

/// The signature of the entry point `__sj_<op>` (`op` is e.g. `sin` or `cplx_sin`).
pub fn signature(op: &str) -> Option<Signature> {
    library().entries.get(op).copied()
}

/// The library's PTX for the entry points `__sj_<op>` of `ops` and all they need, in the order
/// of libm.ptx (which declares functions before their calls).
pub fn functions(ops: &[String]) -> String {
    let lib = library();
    let mut needed: HashSet<usize> = HashSet::new();
    let mut stack: Vec<usize> = Vec::new();
    for op in ops {
        if let Some(idx) = lib.by_name.get(&format!("__sj_{}", op)) {
            stack.extend(idx);
        }
    }
    while let Some(i) = stack.pop() {
        if needed.insert(i) {
            stack.extend(&lib.chunks[i].deps);
        }
    }
    let mut o = String::new();
    for (i, c) in lib.chunks.iter().enumerate() {
        if needed.contains(&i) {
            o.push_str(&c.text);
            o.push('\n');
        }
    }
    o
}

/// All the names the library defines (a kernel must not use one).
pub fn is_library_name(name: &str) -> bool {
    name.starts_with("__sj")
}
